  long double h2 = eval(m2);\n                        if (h1 < h2) right = m2; else left = m1;\n                    }\n                    long double s = (left + right) / 2.0L;\n                    long double Px = ax + s * Sx;\n                    long double Py = ay + s * Sy;\n                    long double phi = atan2l(Py - ti.y, Px - ti.x);\n                    long double δ = angle_diff(ti.a, phi);\n                    long double h = δ - W * s;\n                    if (h <= 0) shot = true;\n                }\n                if (shot){\n                    shooters++;\n                    if (shooters > k) return false;\n                }\n            }\n        }\n        return shooters <= k;\n    };\n\n    // Exponential search to find an upper bound hi with can(hi) == true\n    long double lo = 0.0L, hi = 1.0L;\n    int guard = 0;\n    while (!can(hi) && guard < 80){\n        hi *= 2.0L;\n        guard++;\n        if (hi > 1e18L) break;\n    }\n\n    // Binary search for minimal feasible v\n    for(int it = 0; it < 80; ++it){\n        long double mid = (lo + hi) * 0.5L;\n        if (can(mid)) hi = mid; else lo = mid;\n    }\n\n    cout.setf(std::ios::fixed); cout << setprecision(6) << (double)hi << \"\\n\";\n    return 0;\n}\nCPP\n\ng++ -O2 -std=c++17 main.cpp -o main\n./main << EOF\n0 0 10 0\n1\n5 -5 4.71238 1\n0\nEOF",
